// Serve the last good catalogue while it is still fresh.
//
// This matters more here than for images.json: without it every app that
// opens the Community screen costs this server one api.github.com call, and
// that endpoint allows 60 an hour to an anonymous caller. The cache is what
// keeps one listing call serving every client for the length of the TTL.
const store = $getWorkflowStaticData('global');
const ttlMs = 10 * 60 * 1000;
const fresh = store.body && store.fetchedAt && (Date.now() - store.fetchedAt) < ttlMs;
return [{ json: {
  hit: Boolean(fresh),
  body: fresh ? JSON.parse(store.body) : null,
  cache: 'hit',
} }];

// One item per script folder, so the next node fetches all of them in
// parallel instead of the app walking them one at a time.
//
// A failed listing is not fatal while something is cached: the assemble node
// downstream falls back to it, so a GitHub blip costs freshness, not the
// screen.
const listing = $input.first().json;
const rows = Array.isArray(listing) ? listing : (listing.data ?? []);
if (!Array.isArray(rows) || rows.length === 0) {
  return [{ json: { name: null, listingFailed: true } }];
}
return rows
  .filter((row) => row && row.type === 'dir' && row.name)
  .map((row) => ({ json: {
    name: row.name,
    url: `https://raw.githubusercontent.com/bostrot/wsl-scripts/main/scripts/${row.name}/info.yml`,
  } }));

// Assemble one document out of the per-folder fetches.
//
// Shape is deliberately close to what the app already builds for itself:
// `scripts[].info` is the info.yml text verbatim, so the client keeps using
// its own YAML parser and this endpoint never becomes a second definition of
// what a snippet is. A folder whose info.yml is missing or unreadable is
// dropped, exactly as the app drops it today — one bad entry must not cost
// the whole catalogue.
const store = $getWorkflowStaticData('global');
const items = $input.all();

const scripts = [];
for (const item of items) {
  const j = item.json;
  if (!j || !j.name || j.listingFailed) continue;
  const body = typeof j.data === 'string' ? j.data : (typeof j.body === 'string' ? j.body : null);
  if (!body || j.error !== undefined) continue;
  if (!body.includes('name:')) continue;   // an HTML 404 page is not a manifest
  scripts.push({ name: j.name, info: body });
}

if (scripts.length > 0) {
  const body = {
    generatedAt: new Date().toISOString(),
    source: 'https://github.com/bostrot/wsl-scripts',
    count: scripts.length,
    scripts,
  };
  store.body = JSON.stringify(body);
  store.fetchedAt = Date.now();
  return [{ json: { body, cache: 'miss' } }];
}

// Nothing readable came back. Anything previously good beats an empty list.
if (store.body) {
  return [{ json: { body: JSON.parse(store.body), cache: 'stale' } }];
}
throw new Error('the wsl-scripts catalogue is unavailable upstream and nothing is cached yet');
